/* Ascendance 3.34.4 — Embedded High Fantasy World Map Hotfix
   Makes the illustrated world map self-contained so deployment cannot lose the image asset. */
(()=>{
'use strict';
const V='3.34.4';
const ART_DATA='data:image/webp;base64,';
function ensureStyle(){
 if(document.getElementById('worldMapStyles3344')) return;
 const s=document.createElement('style');
 s.id='worldMapStyles3344';
 s.textContent=`
 #wmArt3344{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:0;pointer-events:none;display:block;opacity:1!important;filter:none!important}
 .wmMap3342{background:#21180f!important;isolation:isolate}
 .wmMap3342:before{z-index:1!important;pointer-events:none!important}
 .wmRegion3342{z-index:4!important}
 .wmRegion3342:hover{z-index:7!important}
 .wmRegion3342.selected{z-index:8!important}
 #wmArtStatus3344{position:absolute;left:10px;bottom:10px;z-index:9;padding:4px 7px;border:1px solid rgba(191,145,58,.55);background:rgba(18,12,6,.80);color:#dcbf78;font:10px Georgia,serif;letter-spacing:.05em;border-radius:3px;pointer-events:none;opacity:0;transition:opacity .2s}
 #wmArtStatus3344.error{opacity:1;background:rgba(78,18,18,.9);color:#ffd1b8}
 `;
 document.head.appendChild(s);
}
function mountArt(){
 const map=document.getElementById('wmMap3342');
 if(!map) return false;
 let img=document.getElementById('wmArt3344');
 if(!img){
   img=document.createElement('img');
   img.id='wmArt3344';
   img.alt='Illustrated world map of Ascendance';
   img.decoding='async';
   img.onload=()=>{ const st=document.getElementById('wmArtStatus3344'); if(st){st.textContent='';st.classList.remove('error')}; map.dataset.artReady='1'; };
   img.onerror=()=>{ let st=document.getElementById('wmArtStatus3344'); if(!st){st=document.createElement('div');st.id='wmArtStatus3344';map.appendChild(st)};st.textContent='MAP ART FAILED TO LOAD';st.classList.add('error'); map.dataset.artReady='0'; };
   map.insertBefore(img,map.firstChild);
 }
 if(img.src!==ART_DATA) img.src=ART_DATA;
 if(!document.getElementById('wmArtStatus3344')){const st=document.createElement('div');st.id='wmArtStatus3344';map.appendChild(st)}
 return true;
}
function boot(){
 ensureStyle();
 mountArt();
 window.ASCENDANCE_BUILD=V;
 window.ASCENDANCE_WORLD_MAP_VERSION=V;
 window.ASCENDANCE_WORLD_MAP_ART='embedded-webp';
 const v=document.querySelector('.frontVersion32714');if(v)v.textContent='v'+V;
 window.ascendance3344=()=>({build:V,art:'embedded-webp',artMounted:!!document.getElementById('wmArt3344'),artReady:document.getElementById('wmMap3342')?.dataset.artReady||'pending',interactiveRegions:document.querySelectorAll('.wmRegion3342').length});
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(boot,70));else setTimeout(boot,70);
setTimeout(boot,600);setTimeout(boot,1600);setTimeout(boot,3000);
})();
